-- 005 · 2026-11-22 · вернуть эмодзи в текст мастера (Инна) на главной, UA и RU
-- Эмодзи записаны HTML-сущностями: колонка value в site_tmplvar_contentvalues в кодировке utf8mb3,
-- 4-байтовые символы (🤍 🥰 🫶) в неё напрямую не записываются.
-- После импорта очистить кэш: Управление → Очистить кэш (или удалить core/cache/*).
SET NAMES utf8mb4;
UPDATE `Impulse_Digital_X_site_tmplvar_contentvalues` SET `value`='<p>Привіт! &#129293; Давайте знайомитися!</p>\n<p>Мене звати Інна, я майстер перманентного макіяжу з досвідом роботи понад 4 роки. &#10024;</p>\n<p>Нещодавно я переїхала до Івано-Франківська, тому з радістю відкриваю для себе нове місто та знайомлюся з вами!</p>\n<p>Для мене перманентний макіяж — це не просто процедура, а мистецтво підкреслювати природну красу, зберігаючи індивідуальність кожної дівчини.</p>\n<p>Я за натуральність, гармонію та делікатний результат, який підкреслює ваші риси й додає впевненості в собі. &#129392;</p>\n<p>Буду рада стати вашим майстром краси та бачити вас серед своїх клієнтів &#129293;<br>Івано-Франківськ, тепер ми знайомі! &#129782;</p>' WHERE `contentid`=193 AND `tmplvarid`=(SELECT `id` FROM `Impulse_Digital_X_site_tmplvars` WHERE `name`='text_bl5_about');
UPDATE `Impulse_Digital_X_site_tmplvar_contentvalues` SET `value`='<p>Привет! &#129293; Давайте знакомиться!</p>\n<p>Меня зовут Инна, я мастер перманентного макияжа с опытом работы более 4 лет. &#10024;</p>\n<p>Недавно я переехала в Ивано-Франковск, поэтому с радостью открываю для себя новый город и знакомлюсь с вами!</p>\n<p>Для меня перманентный макияж — это не просто процедура, а искусство подчёркивать природную красоту, сохраняя индивидуальность каждой девушки.</p>\n<p>Я за естественность, гармонию и деликатный результат, который подчёркивает ваши черты и добавляет уверенности в себе. &#129392;</p>\n<p>Буду рада стать вашим мастером красоты и видеть вас среди своих клиентов &#129293;<br>Ивано-Франковск, теперь мы знакомы! &#129782;</p>' WHERE `contentid`=1 AND `tmplvarid`=(SELECT `id` FROM `Impulse_Digital_X_site_tmplvars` WHERE `name`='text_bl5_about');
